<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {driver,type Driver} from 'driver.js';
import 'driver.js/dist/driver.css';
import {ArrowLeft,ArrowRight,BookOpen,ChartNoAxesCombined,CheckCircle2,ChevronRight,CircleHelp,Compass,LoaderCircle,MessageSquare,Play,RefreshCw,Search,ShieldCheck,Sparkles,X} from 'lucide-vue-next';
import {marked} from 'marked';
import DOMPurify from 'dompurify';
import {searchGuideArticles,visibleGuideSteps,type GuideContent,type GuideProgress,type GuideArticle} from '../lib/product-guide';
const props=defineProps<{page:string|null;user:{id:number;name:string;role:string};blocked:boolean;assistantAvailable?:boolean;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{navigate:[page:string]}>();
const content=ref<GuideContent|null>(null);const loading=ref(false);const starting=ref(false);const helpOpen=ref(false);const welcomeOpen=ref(false);const tab=ref('guides');const query=ref('');const selected=ref<GuideArticle|null>(null);const error=ref('');const dialog=ref<HTMLElement|null>(null);
const welcome=ref<{instance:string;page:string}|null>(null);const pendingWelcome=ref<{instance:string;page:string}|null>(null);let tour:Driver|null=null;let view=0;let skippedView='';let disposed=false;let previousFocus:HTMLElement|null=null;let appWasInert=false;let oldOverflow='';let modalLocked=false;
const pageTitle=computed(()=>props.page?content.value?.pages[props.page]?.title??'esta página':'esta página');
const results=computed(()=>searchGuideArticles(content.value?.articles??[],query.value,props.page));
const modalVisible=computed(()=>helpOpen.value||welcomeOpen.value);
const icons=[Sparkles,ChartNoAxesCombined,ShieldCheck];
function markdown(value:string){return DOMPurify.sanitize(marked.parse(value,{async:false}) as string,{ALLOWED_TAGS:['p','strong','em','ul','ol','li','br','code','h2','h3','blockquote'],ALLOWED_ATTR:[]});}
function active(){return modalVisible.value||Boolean(tour?.isActive());}
function visible(anchor:string){const element=document.querySelector<HTMLElement>(`[data-tour="${CSS.escape(anchor)}"]`);if(!element||!element.getClientRects().length||element.matches(':disabled,[aria-disabled="true"]')||element.closest('[hidden],[inert],[aria-hidden="true"]')||getComputedStyle(element).visibility==='hidden')return false;const rect=element.getBoundingClientRect();return rect.right>0&&rect.left<window.innerWidth;}
function saveProgress(page:string,data:GuideProgress){if(content.value)content.value.progress[page]=data;}
async function event(page:string,instance:string,event:string,step?:string){if(disposed)return;try{const result=await props.request(`/guide/${page}/events`,'POST',{instance_id:instance,event,...(step?{step_id:step}:{})});if(content.value?.progress[page]?.last_instance_id===instance)saveProgress(page,result.progress);}catch{if(!disposed)error.value='Não foi possível salvar o progresso da ajuda. Você pode refazer o tour quando quiser.';}}
function stopTour(){const current=tour;tour=null;current?.destroy();}
async function claim(page:string,mode:'auto'|'manual',expected:number){const instance=crypto.randomUUID();const result=await props.request(`/guide/${page}/start`,'POST',{mode,instance_id:instance});if((expected===view||page==='welcome')&&!disposed)saveProgress(page,result.progress);return{...result,instance};}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const data=await props.request('/guide');if(disposed)return;content.value=data;}catch(e){if(!disposed)error.value=(e as Error).message;}finally{if(!disposed){loading.value=false;await maybeAuto();}}}
async function drive(page:string,mode:'auto'|'manual',expected:number){
 const definition=content.value?.pages[page];if(!definition)return;await nextTick();if(expected!==view||disposed||props.blocked||modalVisible.value)return;
 const steps=visibleGuideSteps(definition.steps,visible);if(!steps.length)return;
 const response=await claim(page,mode,expected);if(!response.should_start||expected!==view||disposed||props.blocked||modalVisible.value)return;
 let displayed=false;const instance=response.instance;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const instanceDriver=driver({animate:!reduced,smoothScroll:!reduced,allowClose:true,allowKeyboardControl:true,disableActiveInteraction:true,overlayClickBehavior:'close',stagePadding:7,stageRadius:10,popoverClass:'ganalise-tour',showProgress:true,progressText:'{{current}} de {{total}}',nextBtnText:'Próximo',prevBtnText:'Voltar',doneBtnText:'Concluir',closeBtnLabel:'Fechar tour',steps:steps.map(step=>({...(step.anchor?{element:`[data-tour="${CSS.escape(step.anchor)}"]`}:{}),popover:{title:step.title,description:step.description}})),onHighlighted:(_element,_step,options)=>{displayed=true;void event(page,instance,'seen',steps[options.index??0]?.id);},onDestroyed:(_element,_step,options)=>{if(tour===instanceDriver)tour=null;if(displayed)void event(page,instance,options.reason==='done'?'completed':'dismissed',steps[options.index??0]?.id);if(props.page===page)skippedView=page;}});
 tour=instanceDriver;instanceDriver.drive();
}
async function maybeAuto(){
 const page=props.page;if(disposed||loading.value||!content.value||!page||props.blocked||modalVisible.value||tour||starting.value||skippedView===page||!content.value.pages[page])return;
 if(pendingWelcome.value){const session=pendingWelcome.value;pendingWelcome.value=null;welcome.value=session;welcomeOpen.value=true;await nextTick();void event('welcome',session.instance,'seen','welcome-intro');return;}
 const expected=view;starting.value=true;
 try{if(!content.value.progress.welcome){const result=await claim('welcome','auto',expected);if(result.should_start&&!disposed)pendingWelcome.value={page:'welcome',instance:result.instance};return;}
  if(!content.value.progress[page])await drive(page,'auto',expected);
 }catch(e){if(expected===view&&!disposed)error.value=(e as Error).message;}
 finally{starting.value=false;if(!disposed&&(expected!==view||pendingWelcome.value)&&!props.blocked&&!modalVisible.value)void maybeAuto();}
}
async function replay(){if(starting.value||props.blocked||!props.page)return;const page=props.page;helpOpen.value=false;selected.value=null;starting.value=true;const expected=++view;error.value='';try{await nextTick();await drive(page,'manual',expected);}catch(e){if(expected===view){helpOpen.value=true;error.value=(e as Error).message;}}finally{starting.value=false;}}
function openHelp(){view++;stopTour();skippedView=props.page??'';helpOpen.value=true;if(!content.value)void load();}
function closeHelp(){helpOpen.value=false;}
async function showWelcome(){if(starting.value)return;pendingWelcome.value=null;const expected=++view;stopTour();starting.value=true;try{const result=await claim('welcome','manual',expected);if(!result.should_start||expected!==view)return;helpOpen.value=false;welcome.value={page:'welcome',instance:result.instance};welcomeOpen.value=true;await nextTick();void event('welcome',result.instance,'seen','welcome-intro');}catch(e){error.value=(e as Error).message;}finally{starting.value=false;}}
async function finishWelcome(startTour=false){const session=welcome.value;welcomeOpen.value=false;welcome.value=null;skippedView=props.page??'';if(session)await event('welcome',session.instance,startTour?'completed':'dismissed','welcome-intro');if(startTour)await replay();}
function go(page:string){if(!content.value?.pages[page]||page==='welcome'||page==='project')return;helpOpen.value=false;emit('navigate',page);}
function chooseArticle(id:string){const article=content.value?.articles.find(item=>item.id===id);if(article){selected.value=article;tab.value='guides';helpOpen.value=true;}}
function focusables(){return [...(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],summary,input:not(:disabled),textarea:not(:disabled),select:not(:disabled),[tabindex="0"]')??[])].filter(element=>element.getClientRects().length);}
function keydown(event:KeyboardEvent){if(!modalVisible.value)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(welcomeOpen.value)void finishWelcome();else closeHelp();return;}if(event.key!=='Tab')return;const elements=focusables();const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}event.stopPropagation();}
function unlockModal(){if(!modalLocked)return;const app=document.getElementById('app');if(app&&!appWasInert)app.removeAttribute('inert');document.body.style.overflow=oldOverflow;modalLocked=false;if(previousFocus?.isConnected)previousFocus.focus();previousFocus=null;}
watch(modalVisible,async open=>{if(open&&!modalLocked){previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;const app=document.getElementById('app');appWasInert=app?.hasAttribute('inert')??false;oldOverflow=document.body.style.overflow;app?.setAttribute('inert','');document.body.style.overflow='hidden';modalLocked=true;}if(!open)unlockModal();else{await nextTick();focusables()[0]?.focus();}});
watch([helpOpen,welcomeOpen],async()=>{if(modalVisible.value){await nextTick();focusables()[0]?.focus();}});
watch(selected,async article=>{if(!article)return;await nextTick();if(helpOpen.value&&selected.value?.id===article.id)dialog.value?.querySelector<HTMLElement>('.guide-article h3')?.focus({preventScroll:true});});
watch(()=>props.page,()=>{view++;stopTour();skippedView='';selected.value=null;void maybeAuto();});
watch(()=>props.blocked,blocked=>{if(blocked){view++;stopTour();}else void maybeAuto();});
onMounted(()=>{window.addEventListener('keydown',keydown,true);void load();});
onUnmounted(()=>{disposed=true;view++;stopTour();unlockModal();window.removeEventListener('keydown',keydown,true);});
defineExpose({openHelp,active,chooseArticle,openPage:go});
</script>
<template>
 <div class="product-guide-system"><Teleport to="body">
  <div v-if="welcomeOpen&&content" class="product-guide-backdrop" @click.self="finishWelcome()"><section ref="dialog" class="product-guide-welcome" role="dialog" aria-modal="true" aria-labelledby="guide-welcome-title"><button class="product-guide-close icon-button" aria-label="Fechar boas-vindas" @click="finishWelcome()"><X :size="19"/></button><span class="guide-welcome-mark"><ChartNoAxesCombined :size="29"/></span><p class="guide-eyebrow">UM PRODUTO INOVADORA</p><h2 id="guide-welcome-title">{{content.welcome.title}}</h2><p class="guide-welcome-description">{{content.welcome.description}}</p><div class="guide-welcome-features"><div v-for="(feature,index) in content.welcome.features" :key="feature.title"><component :is="icons[index]??CheckCircle2" :size="19"/><div><strong>{{feature.title}}</strong><p>{{feature.description}}</p></div></div></div><p v-if="user.role==='viewer'" class="guide-reader-note">Seu perfil permite consultar. As ações de criação e alteração precisam de um perfil autorizado.</p><footer><button class="secondary-button" @click="finishWelcome()">Explorar sozinho</button><button class="primary-button" :disabled="starting||blocked" @click="finishWelcome(true)">Conhecer esta página<ArrowRight :size="16"/></button></footer></section></div>
  <div v-else-if="helpOpen" class="product-guide-backdrop" @click.self="closeHelp"><section ref="dialog" class="product-guide-dialog" role="dialog" aria-modal="true" aria-labelledby="guide-help-title" data-tour="product-help"><header><div class="guide-help-heading"><span class="project-icon blue"><CircleHelp :size="23"/></span><div><p>ESTAMOS AQUI PARA AJUDAR</p><h2 id="guide-help-title">Como podemos ajudar?</h2><small>Orientações para usar o G-Analise IA.</small></div></div><button class="icon-button" aria-label="Fechar ajuda" @click="closeHelp"><X :size="19"/></button></header>
   <div v-if="loading" class="product-guide-loading" role="status"><LoaderCircle class="spin" :size="23"/>Carregando orientações…</div><div v-if="error" class="product-guide-error" role="alert"><p>{{error}}</p><button v-if="!content" class="secondary-button" :disabled="loading" @click="load"><RefreshCw :size="14"/>Tentar novamente</button></div>
   <template v-if="content"><nav v-if="assistantAvailable" class="product-guide-tabs" aria-label="Tipo de ajuda"><button :aria-pressed="tab==='guides'" @click="tab='guides'"><BookOpen :size="16"/>Guias e respostas</button><button :aria-pressed="tab==='assistant'" @click="tab='assistant'"><MessageSquare :size="16"/>Conversar com IA</button></nav>
    <div v-if="tab==='guides'" :key="selected?.id??'guide-list'" class="product-guide-body"><template v-if="selected"><button class="guide-back" @click="selected=null"><ArrowLeft :size="14"/>Voltar às orientações</button><article class="guide-article"><h3 tabindex="-1">{{selected.title}}</h3><div class="guide-markdown" v-html="markdown(selected.body)"></div><div class="guide-article-actions"><button v-for="action in selected.actions" :key="action.page" class="secondary-button" @click="go(action.page)">{{action.label}}<ArrowRight :size="14"/></button></div></article></template><template v-else><div class="guide-page-action"><span><Compass :size="19"/></span><div><strong>Conheça {{pageTitle}}</strong><p>Um passo a passo pelos controles desta página.</p></div><button class="secondary-button" :disabled="starting||blocked||!page" @click="replay"><LoaderCircle v-if="starting" class="spin" :size="14"/><Play v-else :size="14"/>Refazer tour</button></div><p v-if="blocked" class="guide-context-note">O tour ficará disponível depois do carregamento, de concluir a tarefa ou de fechar a janela em uso. Os guias continuam disponíveis abaixo.</p><div class="guide-search"><Search :size="17"/><input v-model="query" type="search" aria-label="Buscar na ajuda" placeholder="Busque por projetos, dashboards, conexões…"></div><div class="guide-article-list"><button v-for="article in results" :key="article.id" @click="selected=article"><span><strong>{{article.title}}</strong><small>{{article.summary}}</small></span><ChevronRight :size="17"/></button></div><p v-if="!results.length" class="guide-empty">Nenhuma orientação encontrada. Tente outra palavra{{assistantAvailable?' ou converse com a IA.':'.'}}</p></template></div>
    <div v-else class="product-guide-ai"><slot name="assistant" :page="page" :articles="content.articles"></slot></div>
    <footer class="product-guide-footer"><button class="text-button" :disabled="starting" @click="showWelcome">Rever boas-vindas</button><span>G-Analise IA · Inovadora</span></footer>
   </template>
  </section></div>
 </Teleport></div>
</template>
<style>
