help-heading p{font-size:8px;letter-spacing:1.7px;font-weight:700;color:#95a3b8;margin:0 0 6px}.guide-help-heading h2{font-size:23px;letter-spacing:-.5px;margin:0 0 7px;color:#293e5d}.guide-help-heading small{font-size:12px;color:#8292aa}.product-guide-tabs{display:flex;gap:7px;padding:12px 29px;border-bottom:1px solid #e8edf5;flex-shrink:0}.product-guide-tabs button{display:flex;align-items:center;gap:8px;padding:9px 13px;border:1px solid transparent;background:transparent;color:#8495ad;border-radius:7px;font-size:12px;font-weight:600}.product-guide-tabs button[aria-pressed=true]{background:#eef5ff;border-color:#d9e7ff;color:#0861ee}.product-guide-body{padding:24px 30px;overflow:auto;min-height:0;flex:1}.product-guide-ai{padding:20px 30px;overflow:hidden;min-height:0;flex:1;display:flex;flex-direction:column}.guide-page-action{display:flex;align-items:center;gap:13px;background:#f3f7ff;border:1px solid #e0eaff;border-radius:11px;padding:17px;margin-bottom:22px}.guide-page-action>span{color:#4d7dca;display:flex}.guide-page-action>div{flex:1;min-width:0}.guide-page-action strong{font-size:13px;color:#46658e}.guide-page-action p{font-size:11px;color:#879bb8;margin:6px 0 0;line-height:1.6}.guide-page-action button{white-space:nowrap;font-size:11px}.guide-search{display:flex;align-items:center;gap:10px;border:1px solid #dce5f1;border-radius:9px;padding:12px;color:#92a4bd;margin-bottom:17px}.guide-search:focus-within{outline:2px solid #0861ee;outline-offset:2px}.guide-search input{width:100%;min-width:0;background:transparent;border:0;outline:0;font:inherit;font-size:12px;color:#456080;padding:0}.guide-article-list{display:grid;gap:8px}.guide-article-list>button{display:flex;align-items:center;justify-content:space-between;gap:16px;border:1px solid #e6ebf3;border-radius:9px;background:#fff;padding:16px;text-align:left;color:#99a9be}.guide-article-list>button:hover{border-color:#cbdcff;background:#fafcff}.guide-article-list>button strong{display:block;font-size:13px;color:#49627f;line-height:1.5}.guide-article-list>button small{display:block;font-size:11px;color:#91a0b5;margin-top:5px;line-height:1.6}.guide-article-list svg{flex-shrink:0}.product-guide-footer{display:flex;align-items:center;justify-content:space-between;padding:17px 30px;border-top:1px solid #e8edf5;gap:12px;flex-shrink:0;background:#fcfdff}.product-guide-footer button{font-size:11px}.product-guide-footer>span{font-size:9px;color:#a0afc3}.product-guide-loading{display:flex;align-items:center;justify-content:center;gap:12px;color:#8293af;padding:50px;font-size:13px}.product-guide-error{padding:15px 25px;background:#fff8ed;color:#94713a;font-size:12px;line-height:1.7}.guide-empty,.guide-context-note{font-size:12px;color:#8a9ab2;line-height:1.8}.guide-context-note{margin:-8px 0 18px}.guide-back{display:inline-flex;gap:7px;align-items:center;border:0;background:transparent;color:#7191b8;font-size:12px;padding:0;margin-bottom:17px}.guide-article h3{font-size:23px;color:#344f73;margin:5px 0 20px;line-height:1.4}.guide-markdown{font-size:13px;line-height:1.9;color:#7086a5;overflow-wrap:anywhere}.guide-markdown p{margin:0 0 16px}.guide-markdown strong{color:#466486}.guide-markdown ul,.guide-markdown ol{padding-left:24px;margin:16px 0}.guide-markdown li{margin:9px 0}.guide-article-actions{display:flex;gap:10px;flex-wrap:wrap;margin:25px 0 6px}.guide-article-actions button{font-size:12px}.ganalise-tour.driver-popover{font-family:inherit;background:#fff;color:#3b5578;border:1px solid #dce7f6;border-radius:13px;box-shadow:0 14px 50px #142c4d24;max-width:min(360px,calc(100vw - 30px));padding:21px}.ganalise-tour .driver-popover-title{font-family:inherit;font-size:18px;letter-spacing:-.3px;color:#314d72;line-height:1.4;margin-right:17px}.ganalise-tour .driver-popover-description{font-family:inherit;font-size:12px;line-height:1.8;color:#7d91ae;margin-top:12px}.ganalise-tour .driver-popover-progress-text{font-size:10px;color:#96a5ba}.ganalise-tour .driver-popover-footer button{font-family:inherit;border-radius:6px;padding:8px 12px;font-size:11px;text-shadow:none;box-shadow:none;min-height:34px}.ganalise-tour .driver-popover-next-btn{background:#0861ee;border-color:#0861ee;color:#fff}.ganalise-tour .driver-popover-prev-btn{background:#fff;border-color:#dfe7f2;color:#7288a7}.ganalise-tour .driver-popover-close-btn{color:#9caec6}.ganalise-tour button:focus-visible{outline:2px solid #0861ee;outline-offset:3px}
@media(max-width:600px){.product-guide-backdrop{padding:12px}.product-guide-welcome,.product-guide-dialog{max-height:calc(100dvh - 24px);border-radius:14px;width:100%}.product-guide-welcome{padding:29px 23px}.product-guide-welcome h2{font-size:24px}.product-guide-welcome footer{flex-direction:column-reverse}.product-guide-dialog>header{padding:22px 19px}.guide-help-heading h2{font-size:20px}.guide-help-heading p{font-size:7px}.guide-help-heading{gap:10px}.product-guide-body,.product-guide-ai{padding:19px}.product-guide-tabs{padding:10px 18px}.product-guide-tabs button{padding:8px;font-size:11px}.guide-page-action{flex-wrap:wrap;padding:14px;gap:10px}.guide-page-action>div{min-width:180px}.guide-page-action button{margin-left:auto}.product-guide-footer{padding:15px 19px}.guide-article h3{font-size:20px}.product-guide-footer>span{font-size:8px}.guide-article-actions{flex-direction:column}}
